"""Observe Save System through ordinary controls on a private marker OS."""
from pathlib import Path
import argparse,hashlib,json,time
from PIL import Image
from probe_base import ROOT,HERE,ObservedRuntime
from s760_runtime import RuntimeConfig

p=argparse.ArgumentParser(description=__doc__)
p.add_argument('--output',type=Path,required=True)
p.add_argument('--system',type=Path,default=HERE/'marker-os.img')
a=p.parse_args();work=a.output.resolve();work.mkdir(parents=True,exist_ok=False)
cfg=RuntimeConfig(ROOT/'mame-source/mames760.exe',ROOT/'roms/BOOT/Roland_S-760_v1.11.BIN',a.system.resolve(),work/'runtime',HERE/'blank-1440.img',sound=False,throttle=False)
inputs=[cfg.executable,cfg.boot_rom,cfg.system_disk,cfg.sample_disk,ROOT/'S760224.IMG',ROOT/'roms/System/S760224.IMG',Path(__file__),HERE/'probe_base.py',HERE/'observer.lua',ROOT/'scripts/s760_runtime.py',ROOT/'scripts/s760_runtime.lua']
hashes={str(p.relative_to(ROOT)):hashlib.sha256(p.read_bytes()).hexdigest() for p in inputs}
actions=[]
with ObservedRuntime(cfg) as rt:
 def wait(seconds):
  target=rt.request('status')[0]['seconds']+seconds;limit=time.monotonic()+120
  while rt.request('status')[0]['seconds']<target:
   assert time.monotonic()<limit,'Native machine time stopped'
   time.sleep(.01)
 def button(port,name):
  rt.request('button',port=port,name=name,down=True);wait(.12)
  rt.request('button',port=port,name=name,down=False);wait(.5)
 def pointer(x,y):rt.request('pointer',x=x,y=y);wait(1)
 def click(x,y):pointer(x,y);button(':NATIVE_MOUSE_BUTTONS','Mouse Left')
 def shot(name):
  assert name.replace('-','').isalnum()
  reply=rt.request('frames');Image.frombytes('RGBA',(640,480),reply[1][0][6:]).save(work/(name+'.png'))
  row=dict(name=name,snapshot=rt.snapshot_count,seconds=rt.request('status')[0]['seconds'])
  actions.append(row);print(json.dumps(row),flush=True)
 wait(22);shot('boot');button(':NATIVE_MEDIA','Insert Sample Floppy');click(118,5);shot('disk-menu')
 rt.request('pause');print('READY',flush=True)
 request_id=0;deadline=time.monotonic()+1200
 while time.monotonic()<deadline:
  path=work/f'command-{request_id:03}.json'
  if not path.exists():time.sleep(.05);continue
  commands=json.loads(path.read_text());quit_requested=False
  for c in commands:
   actions.append(dict(command=c));op=c['op']
   if op=='quit':quit_requested=True;break
   rt.request('resume')
   if op=='click':click(c['x'],c['y'])
   elif op=='pointer':pointer(c['x'],c['y'])
   elif op=='wait':wait(c['seconds'])
   elif op=='shot':shot(c['name'])
   elif op=='button':button(c['port'],c['name'])
   elif op=='dial':pointer(c['x'],c['y']);rt.request('dial',id='ALPHA',delta=c['delta']);wait(1)
   elif op=='export':rt.export_media(work/c['name'])
   else:raise ValueError(op)
   rt.request('pause')
  (work/f'done-{request_id:03}.json').write_text(json.dumps(commands))
  request_id+=1
  if quit_requested:break
 else:raise TimeoutError('Exploration deadline')
assert all(hashlib.sha256((ROOT/p).read_bytes()).hexdigest()==h for p,h in hashes.items())
(work/'result.json').write_text(json.dumps(dict(identities=hashes,actions=actions,source_unchanged=True),indent=2)+'\n')
